<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '@/stores/auth';import {errorMessage} from '@/services/api';const u=ref('admin'),p=ref('Admin123*'),loading=ref(false),error=ref('');const a=useAuthStore(),r=useRouter();async function go(){loading.value=true;error.value='';try{await a.login(u.value.trim(),p.value);r.push('/dashboard')}catch(e){error.value=errorMessage(e)}finally{loading.value=false}};</script><template><div class="login-page"><div class="login-art"><div class="art-copy"><span class="eyebrow">Plataforma aseguradora</span><h1>Decisiones de riesgo claras, rápidas y trazables.</h1><p>Centraliza cotizaciones, emisión, siniestros y renovaciones con una experiencia simple.</p><div class="art-metrics"><div><b>100%</b><span>Trazabilidad</span></div><div><b>Onion</b><span>Arquitectura</span></div><div><b>24/7</b><span>Disponibilidad</span></div></div></div></div><div class="login-panel"><form class="login-card" @submit.prevent="go"><div class="logo-large">A</div><h2>Bienvenido</h2><p>Ingresa para administrar Andina Seguros.</p><label>Usuario<input v-model="u" autocomplete="username" required/></label><label>Contraseña<input v-model="p" type="password" autocomplete="current-password" required/></label><div v-if="error" class="alert error">{{error}}</div><button class="primary wide" :disabled="loading">{{loading?'Ingresando…':'Iniciar sesión'}}</button><small>Usuario inicial sugerido: admin / Admin123*</small></form></div></div></template>
